        List<GalleryItem> items = galleryItemRepository.findByCategory(category);
        if (items.isEmpty()) {
            throw new ResourceNotFoundException("No gallery items found for category: " + category);
        }
        return items.stream()
                .map(this::convertToDto)
                .collect(Collectors.toList());
    }

